@FiniteQM.ClassicalExclusion.affine_image_finite_polytope : ∀ {E : Type u_1} {F : Type u_2} [inst : AddCommGroup E]
  [inst_1 : Module ℝ E] [inst_2 : AddCommGroup F] [inst_3 : Module ℝ F] (f : E →ᵃ[ℝ] F) {S : Set E},
  FiniteQM.ClassicalExclusion.FinitePolytope S → FiniteQM.ClassicalExclusion.FinitePolytope (⇑f '' S)

@FiniteQM.ReconstructionGeometry.Composite.marginal_image : ∀ {a b c : ℕ} {A : FiniteQM.ReconstructionGeometry.System a}
  {B : FiniteQM.ReconstructionGeometry.System b} {AB : FiniteQM.ReconstructionGeometry.System c}
  (C : FiniteQM.ReconstructionGeometry.Composite A B AB), ⇑C.margB '' AB.states = B.states

@FiniteQM.ReconstructionGeometry.Composite.marginal_finite_polytope : ∀ {a b c : ℕ}
  {A : FiniteQM.ReconstructionGeometry.System a} {B : FiniteQM.ReconstructionGeometry.System b}
  {AB : FiniteQM.ReconstructionGeometry.System c} (C : FiniteQM.ReconstructionGeometry.Composite A B AB),
  FiniteQM.ClassicalExclusion.FinitePolytope AB.states → FiniteQM.ClassicalExclusion.FinitePolytope B.states

@FiniteQM.ReconstructionGeometry.Composite.no_polytope_composite_with_ball : ∀ {a b c : ℕ}
  {A : FiniteQM.ReconstructionGeometry.System a} {B : FiniteQM.ReconstructionGeometry.System b}
  {AB : FiniteQM.ReconstructionGeometry.System c} (C : FiniteQM.ReconstructionGeometry.Composite A B AB)
  (e : FiniteQM.ReconstructionGeometry.Space b ≃ᵃ[ℝ] FiniteQM.ClassicalExclusion.R3),
  ⇑e '' B.states = FiniteQM.ClassicalExclusion.ball3 → ¬FiniteQM.ClassicalExclusion.FinitePolytope AB.states

@FiniteQM.ReconstructionGeometry.Representation.dim_eq : ∀
  {catalogue : FiniteQM.ReconstructionGeometry.JordanStateCatalogue} {n : ℕ}
  {A : FiniteQM.ReconstructionGeometry.System n} (R : FiniteQM.ReconstructionGeometry.Representation catalogue A),
  A.dim = R.tag.dim

@FiniteQM.ReconstructionGeometry.Representation.inverse_image_states : ∀
  {catalogue : FiniteQM.ReconstructionGeometry.JordanStateCatalogue} {n : ℕ}
  {A : FiniteQM.ReconstructionGeometry.System n} (R : FiniteQM.ReconstructionGeometry.Representation catalogue A),
  ⇑R.equivalence.symm '' (catalogue.model R.tag).states = A.states

@FiniteQM.ReconstructionGeometry.Representation.classical_polytope : ∀
  {catalogue : FiniteQM.ReconstructionGeometry.JordanStateCatalogue} {n : ℕ}
  {A : FiniteQM.ReconstructionGeometry.System n} (R : FiniteQM.ReconstructionGeometry.Representation catalogue A),
  R.tag.IsClassical → FiniteQM.ClassicalExclusion.FinitePolytope A.states

@FiniteQM.ReconstructionGeometry.Representation.qubit_ball : ∀
  {catalogue : FiniteQM.ReconstructionGeometry.JordanStateCatalogue} {n : ℕ}
  {A : FiniteQM.ReconstructionGeometry.System n} (R : FiniteQM.ReconstructionGeometry.Representation catalogue A)
  {s : FiniteQM.ReconstructionArithmetic.SimpleEJA},
  R.tag.summands = [s] → s.IsQubitAlgebra → ∃ e, ⇑e '' A.states = FiniteQM.ClassicalExclusion.ball3

@FiniteQM.ReconstructionGeometry.no_classical_composite_with_qubit : ∀
  {catalogue : FiniteQM.ReconstructionGeometry.JordanStateCatalogue} {a b c : ℕ}
  {A : FiniteQM.ReconstructionGeometry.System a} {B : FiniteQM.ReconstructionGeometry.System b}
  {AB : FiniteQM.ReconstructionGeometry.System c} (C : FiniteQM.ReconstructionGeometry.Composite A B AB)
  (RAB : FiniteQM.ReconstructionGeometry.Representation catalogue AB)
  (RB : FiniteQM.ReconstructionGeometry.Representation catalogue B) {s : FiniteQM.ReconstructionArithmetic.SimpleEJA},
  RB.tag.summands = [s] → s.IsQubitAlgebra → ¬RAB.tag.IsClassical

@FiniteQM.ReconstructionGeometry.rank_two_dim_four_ball : ∀
  {catalogue : FiniteQM.ReconstructionGeometry.JordanStateCatalogue} {n : ℕ}
  {A : FiniteQM.ReconstructionGeometry.System n} (R : FiniteQM.ReconstructionGeometry.Representation catalogue A),
  A.rank = 2 → A.dim = 4 → ∃ e, ⇑e '' A.states = FiniteQM.ClassicalExclusion.ball3

@FiniteQM.ReconstructionGeometry.no_classical_factor_with_qubit : ∀
  {catalogue : FiniteQM.ReconstructionGeometry.JordanStateCatalogue} {a b c : ℕ}
  {A : FiniteQM.ReconstructionGeometry.System a} {B : FiniteQM.ReconstructionGeometry.System b}
  {AB : FiniteQM.ReconstructionGeometry.System c} (C : FiniteQM.ReconstructionGeometry.Composite A B AB)
  (RA : FiniteQM.ReconstructionGeometry.Representation catalogue A)
  (RB : FiniteQM.ReconstructionGeometry.Representation catalogue B)
  (RAB : FiniteQM.ReconstructionGeometry.Representation catalogue AB),
  RAB.tag.IsSimple ∨ RAB.tag.IsClassical →
    AB.dim = A.dim * B.dim → A.rank * B.rank ≤ AB.rank → 2 ≤ A.rank → B.rank = 2 → B.dim = 4 → ¬RA.tag.IsClassical

@FiniteQM.ConvexSubstitution.image_substitution : ∀ {E : Type u_1} {F : Type u_2} {G : Type u_3} [inst : AddCommGroup E]
  [inst_1 : Module ℝ E] [inst_2 : AddCommGroup F] [inst_3 : Module ℝ F] [inst_4 : AddCommGroup G] [inst_5 : Module ℝ G]
  (f : E →ᵃ[ℝ] F) (g : F →ᵃ[ℝ] G) (S : Set E), ⇑(g.comp f) '' S = ⇑g '' ⇑f '' S

@FiniteQM.ConvexSubstitution.image_associativity : ∀ {E : Type u_1} {F : Type u_2} {G : Type u_3} {H : Type u_4}
  [inst : AddCommGroup E] [inst_1 : Module ℝ E] [inst_2 : AddCommGroup F] [inst_3 : Module ℝ F]
  [inst_4 : AddCommGroup G] [inst_5 : Module ℝ G] [inst_6 : AddCommGroup H] [inst_7 : Module ℝ H] (f : E →ᵃ[ℝ] F)
  (g : F →ᵃ[ℝ] G) (h : G →ᵃ[ℝ] H) (S : Set E), ⇑((h.comp g).comp f) '' S = ⇑(h.comp (g.comp f)) '' S

@FiniteQM.ConvexSubstitution.finite_polytope_substitution : ∀ {E : Type u_1} {F : Type u_2} {G : Type u_3}
  [inst : AddCommGroup E] [inst_1 : Module ℝ E] [inst_2 : AddCommGroup F] [inst_3 : Module ℝ F]
  [inst_4 : AddCommGroup G] [inst_5 : Module ℝ G] (f : E →ᵃ[ℝ] F) (g : F →ᵃ[ℝ] G) {S : Set E},
  FiniteQM.ClassicalExclusion.FinitePolytope S → FiniteQM.ClassicalExclusion.FinitePolytope (⇑(g.comp f) '' S)
